pflichtteil_gemischter_ausgleich_mit_anrechnung <- function(gruppennachlass=NULL, miterben=NULL, berechtigter_id=NULL, gruppenquote_am_gesamtnachlass=NULL, zugleich_anrechenbarer_zuwendungswert=NULL, reiner_anrechnungswert_2315=NULL, hinterlassener_erbteilwert=NULL, ausgleichungsmodell=NULL, methodennachweis=NULL) {
 n <- .geld(gruppennachlass);q <- .zahleneingabe(gruppenquote_am_gesamtnachlass);a <- .geld(zugleich_anrechenbarer_zuwendungswert);rein <- .geld(reiner_anrechnungswert_2315);hinter <- .geld(hinterlassener_erbteilwert);name <- .text(berechtigter_id,'berechtigter_id')
 if(.vergleichen(q,.bruch(0))<=0||.vergleichen(q,.bruch(1))>0) .fehler('gruppenquote_am_gesamtnachlass','Positive Quote h\u00f6chstens1erforderlich.')
 masse <- .addieren(n,.multiplizieren(rein,q));teilung <- erbteilung_gemischter_ausgleich_mit_ueberempfang(.bruchteile(masse),miterben,ausgleichungsmodell,methodennachweis)$wert
 index <- which(vapply(miterben,function(p)identical(p$person_id,name),logical(1)))
 if(!length(index)) .fehler('berechtigter_id','Berechtigter muss Gruppenmitglied sein.')
 if(.vergleichen(a,.geld(miterben[[index]]$ausgleichungswert_zuwendungen))>0) .fehler('zugleich_anrechenbarer_zuwendungswert','Doppelanrechnung h\u00f6chstens eigener enthaltener Zuwendungswert.')
 erb <- .geld(teilung$zuteilungen[[index]]$erbteil_nach_gemischtem_ausgleich);vor <- .multiplizieren(erb,.bruch(1,2));halb <- .multiplizieren(a,.bruch(1,2));pflicht <- .subtrahieren(.subtrahieren(vor,halb),rein);if(.vergleichen(pflicht,.bruch(0))<0)pflicht <- .bruch(0)
 mehr <- .subtrahieren(pflicht,hinter);if(.vergleichen(mehr,.bruch(0))<0)mehr <- .bruch(0)
 wert <- list(hypothetischer_gruppennachlass=.bruchteile(masse),hypothetischer_gesetzlicher_erbteil=.bruchteile(erb),pflichtteil_vor_anrechnungen=.bruchteile(vor),halber_doppelanrechnungswert=.bruchteile(halb),pflichtteilswert=.bruchteile(pflicht),mehrbetrag_gegenueber_hinterlassenem_erbteil=.bruchteile(mehr))
 eingaben <- list(gruppennachlass=gruppennachlass, miterben=miterben, berechtigter_id=berechtigter_id, gruppenquote_am_gesamtnachlass=gruppenquote_am_gesamtnachlass, zugleich_anrechenbarer_zuwendungswert=zugleich_anrechenbarer_zuwendungswert, reiner_anrechnungswert_2315=reiner_anrechnungswert_2315, hinterlassener_erbteilwert=hinterlassener_erbteilwert, ausgleichungsmodell=ausgleichungsmodell, methodennachweis=methodennachweis)
 ergebnis <- .ergebnis(wert,"EUR","BGB_PFLICHTTEIL_GEMISCHTER_AUSGLEICH_MIT_ANRECHNUNG",eingaben,list(list(operation="Reine2315-Zuwendung anteilig zur hypothetischen Gruppenmasse addieren, gemischtes Modell berechnen, Anteil halbieren und getrennte Anrechnungen abziehen.")),eingaben)
 ergebnis$hinweise <- list("Bedingte2316/2315-Komposition: reine eigene2315-Zuwendung mit gesetzlicher Gruppenquote zur Gruppenmasse hinzuf\u00fcgen; vorhandenen ausdr\u00fccklich ausgew\u00e4hlten2055/2056/2057a-Kern auf hypothetische Masse anwenden. Eigenen hypothetischen gesetzlichen Anteil halbieren; zugleich ausgleichungspflichtige2315-Zuwendung nach2316IVnur halb, zus\u00e4tzliche reine2315-Zuwendung vollst\u00e4ndig abziehen; positiver Rest und2316II-Mehrbetrag. Gruppenquote verhindert volle Hinzurechnung zur Teilgruppe bei weiteren gesetzlichen Erben. Kein doppelt erfasstes Geschenk, keine automatische Bewertung/Kaufkraftbereinigung. Kombination und Reihenfolge sind rechtliche Modellvoraussetzungen, insbesondere zugleich leistende \u00dcberempf\u00e4nger bleiben keine automatisch gel\u00f6ste Auslegungsfrage. Unterschiedliche Wertans\u00e4tze derselben Doppelzuwendung und2325/2327-Erg\u00e4nzung separat. Rechtlicher Gruppenausschluss durch Erbverzicht und Ausstattungsschutz2316IIIvorqualifiziert.")
 ergebnis
}
